package com.humanisedbaritone.path;

import com.humanisedbaritone.world.Blk;

/**
 * Generates the moves available from a standing position together with their cost in ticks. A position is the cell of
 * the player's feet; the floor is the block below it. The same code validates a move again right before it is run.
 */
public final class Moves {
	/** RUN is never generated by {@link #expand}: {@link Smooth} merges flat stretches of open ground into one straight run afterwards. */
	public enum Kind { TRAVERSE, DIAGONAL, ASCEND, DESCEND, VERTICAL, PILLAR, DIG_DOWN, PARKOUR, RUN }

	private static final int[] DX = {1, -1, 0, 0}, DZ = {0, 0, 1, -1};
	private static final int[] DIAG_X = {1, 1, -1, -1}, DIAG_Z = {1, -1, 1, -1};

	private Moves() {
	}

	/** Reusable result buffer. */
	public static final class Out {
		public int n;
		public final Kind[] kind = new Kind[112];
		public final int[] x = new int[112], y = new int[112], z = new int[112];
		public final double[] cost = new double[112];
		/** The move ends on a block that has to be placed first, so the next move can rely on a floor that is not in the world yet. */
		public final boolean[] placed = new boolean[112];

		public void reset() {
			n = 0;
		}

		void add(Kind k, int nx, int ny, int nz, double c) {
			add(k, nx, ny, nz, c, false);
		}

		void add(Kind k, int nx, int ny, int nz, double c, boolean floorPlaced) {
			if (c >= Costs.INF || n >= kind.length) return;
			kind[n] = k;
			x[n] = nx;
			y[n] = ny;
			z[n] = nz;
			cost[n] = c;
			placed[n] = floorPlaced;
			n++;
		}
	}

	public static void expand(Ctx c, int x, int y, int z, Out o) {
		expand(c, x, y, z, false, o);
	}

	/** @param virtualFloor the floor under this position is a block the plan places on the way here */
	public static void expand(Ctx c, int x, int y, int z, boolean virtualFloor, Out o) {
		boolean water = c.swim && c.water(x, y, z);
		boolean ladder = c.climbable(x, y, z);
		boolean ground = virtualFloor || c.canStandOn(x, y - 1, z);
		// a block the plan places itself is a plain full block; soul sand, honey and the like change what can be done from them
		int floor = virtualFloor ? 0 : c.f(x, y - 1, z);
		boolean jump = water || (floor & Blk.NO_JUMP) == 0;
		for (int i = 0; i < 4; i++) {
			traverse(c, x, y, z, DX[i], DZ[i], water, ground && (floor & Blk.SUNK) == 0, o);
			if (jump) ascend(c, x, y, z, DX[i], DZ[i], water, o);
			descend(c, x, y, z, DX[i], DZ[i], o);
			if (ground && jump && c.parkour) parkour(c, x, y, z, DX[i], DZ[i], floor, o);
		}
		if (c.diagonal) for (int i = 0; i < 4; i++) diagonal(c, x, y, z, DIAG_X[i], DIAG_Z[i], water, o);
		vertical(c, x, y, z, water, ladder, o);
		if (ground) {
			// standing on soul sand the planner cannot bridge, but it can pillar onto a full block first and bridge from that
			if (c.pillar && jump) pillar(c, x, y, z, o);
			if (c.digDown && !virtualFloor) digDown(c, x, y, z, o);
		}
	}

	/** True when {@code kind} from (x,y,z) to (tx,ty,tz) can still be done; used just before executing a step. */
	public static boolean stillValid(Ctx c, Kind kind, int x, int y, int z, int tx, int ty, int tz) {
		Out o = new Out();
		expand(c, x, y, z, o);
		for (int i = 0; i < o.n; i++) if (o.kind[i] == kind && o.x[i] == tx && o.y[i] == ty && o.z[i] == tz) return true;
		return false;
	}

	private static double danger(Ctx c, int x, int y, int z) {
		return c.lavaPenalty(x, y, z) + c.mobPenalty(x, y, z);
	}

	// ------------------------------------------------------------------ traverse

	/** @param canBridge standing on a full-height floor: sneaking at its edge leaves room to place a block beside it */
	private static void traverse(Ctx c, int x, int y, int z, int dx, int dz, boolean water, boolean canBridge, Out o) {
		int nx = x + dx, nz = z + dz;
		if (!c.loaded(nx, nz)) return;
		double clear = c.clearColumn(nx, y, nz);
		if (clear >= Costs.INF) return;
		boolean destWater = c.swim && c.water(nx, y, nz);
		boolean destLadder = c.climbable(nx, y, nz);
		double place = 0, base;
		if (c.canStandOn(nx, y - 1, nz) || destWater || destLadder) {
			base = water || destWater ? Costs.WATER : Costs.WALK;
			if ((c.f(nx, y - 1, nz) & Blk.SLOW) != 0) base *= 2.5;
		} else {
			// nothing to stand on: bridge across, sneaking slowly along the edge
			if (!canBridge || !c.bridge || !c.allowPlace || !c.hasBlocks || !c.replaceable(nx, y - 1, nz) || c.reserved(nx, y - 1, nz)) return;
			place = c.placeCost();
			base = Costs.WALK * 1.8;
		}
		double cost = (base + clear + place + danger(c, nx, y, nz)) * c.jitter(nx, y, nz);
		o.add(Kind.TRAVERSE, nx, y, nz, cost, place > 0);
	}

	// ------------------------------------------------------------------ diagonal

	private static void diagonal(Ctx c, int x, int y, int z, int dx, int dz, boolean water, Out o) {
		int nx = x + dx, nz = z + dz;
		if (!c.loaded(nx, nz)) return;
		if (!c.passable(nx, y, nz) || !c.passable(nx, y + 1, nz)) return;
		if (!c.passable(x + dx, y, z) || !c.passable(x + dx, y + 1, z) || !c.passable(x, y, z + dz) || !c.passable(x, y + 1, z + dz)) return;
		boolean destWater = c.swim && c.water(nx, y, nz);
		if (!c.canStandOn(nx, y - 1, nz) && !destWater && !c.climbable(nx, y, nz)) return;
		double base = water || destWater || c.water(x + dx, y, z) || c.water(x, y, z + dz) ? Costs.WATER : Costs.WALK;
		if ((c.f(nx, y - 1, nz) & Blk.SLOW) != 0) base *= 2.5;
		double cost = (base * Costs.SQRT2 + danger(c, nx, y, nz)) * c.jitter(nx, y, nz);
		o.add(Kind.DIAGONAL, nx, y, nz, cost);
	}

	// ------------------------------------------------------------------ ascend

	private static void ascend(Ctx c, int x, int y, int z, int dx, int dz, boolean water, Out o) {
		int nx = x + dx, nz = z + dz;
		if (!c.loaded(nx, nz)) return;
		double head = c.clearCost(x, y + 2, z); // room to jump
		if (head >= Costs.INF) return;
		double clear = c.clearColumn(nx, y + 1, nz);
		if (clear >= Costs.INF) return;
		double place = 0;
		if (!c.canStandOn(nx, y, nz)) {
			// step up onto a block we place first
			if (!c.canPlace(nx, y, nz)) return;
			place = c.placeCost() + (c.building() ? 14 : 0); // a staircase of placed blocks is shaky to climb, and while building a pillar is the sure way up
		}
		double cost = ((water ? Costs.WATER : Costs.WALK) + Costs.JUMP + c.jumpPenalty + head + clear + place + danger(c, nx, y + 1, nz)) * c.jitter(nx, y + 1, nz);
		o.add(Kind.ASCEND, nx, y + 1, nz, cost, place > 0);
	}

	// ------------------------------------------------------------------ descend / fall

	private static void descend(Ctx c, int x, int y, int z, int dx, int dz, Out o) {
		int nx = x + dx, nz = z + dz;
		if (!c.loaded(nx, nz)) return;
		double clear = c.clearColumn(nx, y, nz);
		if (clear >= Costs.INF) return;
		if (c.canStandOn(nx, y - 1, nz) || c.swim && c.water(nx, y, nz) || c.climbable(nx, y, nz)) return; // that is a traverse
		boolean bucket = c.clutch && c.hasWaterBucket;
		int limit = Math.max(c.maxFall, bucket ? c.maxFallBucket : 0);
		for (int fy = y - 1; fy >= c.minY && y - fy <= Math.max(limit, 40); fy--) {
			int drop = y - fy;
			boolean wet = c.swim && c.water(nx, fy, nz);
			boolean rung = c.climbable(nx, fy, nz);
			if (!c.passable(nx, fy, nz) && !wet) return; // hit something that is not a floor we checked below
			boolean floor = c.canStandOn(nx, fy - 1, nz);
			if (!floor && !wet && !rung) continue;
			double extra = 0;
			if (!wet && !rung && drop > c.maxFall) {
				if (!bucket || drop > c.maxFallBucket) return;
				extra = Costs.CLUTCH;
			}
			double cost = Costs.WALK_OFF + Costs.FALL[Math.min(drop, 255)] + (drop > 1 ? Costs.CENTER_AFTER_FALL : 0) + clear + extra;
			cost = (cost + danger(c, nx, fy, nz)) * c.jitter(nx, fy, nz);
			o.add(Kind.DESCEND, nx, fy, nz, cost);
			return;
		}
	}

	// ------------------------------------------------------------------ vertical

	private static void vertical(Ctx c, int x, int y, int z, boolean water, boolean ladder, Out o) {
		if (ladder) {
			if (c.climbable(x, y + 1, z) && c.passable(x, y + 2, z)) o.add(Kind.VERTICAL, x, y + 1, z, Costs.LADDER_UP * c.jitter(x, y + 1, z));
			if (c.climbable(x, y - 1, z)) o.add(Kind.VERTICAL, x, y - 1, z, Costs.LADDER_DOWN * c.jitter(x, y - 1, z));
		}
		if (water) {
			if (c.water(x, y + 1, z) && c.passable(x, y + 2, z)) o.add(Kind.VERTICAL, x, y + 1, z, Costs.WATER * 0.85 * c.jitter(x, y + 1, z));
			if (c.water(x, y - 1, z)) o.add(Kind.VERTICAL, x, y - 1, z, Costs.WATER * 0.6 * c.jitter(x, y - 1, z));
		}
	}

	// ------------------------------------------------------------------ pillar / dig

	private static void pillar(Ctx c, int x, int y, int z, Out o) {
		if (!c.allowPlace || !c.hasBlocks) return;
		double head = c.clearCost(x, y + 2, z);
		if (head >= Costs.INF || !c.passable(x, y + 1, z) || c.reserved(x, y, z)) return;
		double cost = (Costs.JUMP + 9 + c.jumpPenalty + c.placeCost() + head) * c.jitter(x, y + 1, z);
		o.add(Kind.PILLAR, x, y + 1, z, cost, true);
	}

	private static void digDown(Ctx c, int x, int y, int z, Out o) {
		if (!c.allowBreak) return;
		double dig = c.clearCost(x, y - 1, z);
		if (dig <= 0 || dig >= Costs.INF) return;
		// after the floor is gone we drop until something solid (or water) stops us
		for (int fy = y - 1; fy >= c.minY && y - fy <= c.maxFall; fy--) {
			boolean wet = c.swim && c.water(x, fy, z);
			if (Blk.isLava(c.get(x, fy, z)) || fy < y - 1 && !c.passable(x, fy, z)) return;
			if (c.canStandOn(x, fy - 1, z) || wet || c.climbable(x, fy, z)) {
				int drop = y - fy;
				double cost = (dig + Costs.FALL[drop] + Costs.CENTER_AFTER_FALL + danger(c, x, fy, z)) * c.jitter(x, fy, z);
				o.add(Kind.DIG_DOWN, x, fy, z, cost);
				return;
			}
		}
	}

	// ------------------------------------------------------------------ parkour

	private static final double[] PARKOUR_RISK = {0, 0, 0, 7, 22, 50};

	/** @param floor flags of the take-off block */
	private static void parkour(Ctx c, int x, int y, int z, int dx, int dz, int floor, Out o) {
		if (!c.passable(x, y + 2, z)) return; // head room for the take-off
		if (c.canStandOn(x + dx, y - 1, z + dz)) return; // solid ground ahead: just walk
		// soul sand or slime underfoot gives no speed, and a run-up on ice slides away: only the shortest jump
		int maxL = c.sprint && (floor & (Blk.SLOW | Blk.SLIPPERY)) == 0 ? Math.min(5, c.maxGap + 1) : 2;
		// free running room behind the take-off block decides how long a jump is realistic
		int run = 0;
		for (int k = 1; k <= 4; k++) {
			int bx = x - dx * k, bz = z - dz * k;
			if (!c.canStandOn(bx, y - 1, bz) || (c.f(bx, y - 1, bz) & (Blk.SLOW | Blk.SLIPPERY)) != 0 || !c.passable(bx, y, bz) || !c.passable(bx, y + 1, bz)) break;
			run++;
		}
		for (int len = 2; len <= maxL; len++) {
			// the columns we fly over must be free up to head height plus the jump arc
			int fx = x + dx * (len - 1), fz = z + dz * (len - 1);
			if (!c.passable(fx, y, fz) || !c.passable(fx, y + 1, fz) || !c.passable(fx, y + 2, fz)) return;
			int lx = x + dx * len, lz = z + dz * len;
			if (!c.loaded(lx, lz)) return;
			if (len == 3 && run < 1 || len == 4 && run < 3 || len == 5 && run < 4) continue;
			for (int dy = 1; dy >= -2; dy--) {
				if (dy == 1 && (!c.parkourUp || len > 3 || len == 3 && !c.sprint || (floor & Blk.SUNK) != 0)) continue; // from a sunk floor the jump peaks too low
				if (dy == -2 && len == 2) continue;
				int ty = y + dy;
				if (!c.canStandOn(lx, ty - 1, lz) || !c.passable(lx, ty, lz) || !c.passable(lx, ty + 1, lz)) continue;
				if ((c.f(lx, ty - 1, lz) & Blk.SLIPPERY) != 0) continue; // landing on ice with that speed slides on for blocks
				double cost = Costs.SPRINT * len + Costs.JUMP + Costs.PARKOUR + PARKOUR_RISK[len] + c.jumpPenalty + (dy < 0 ? Costs.FALL[-dy] : 0) + (dy > 0 ? 4 : 0);
				o.add(Kind.PARKOUR, lx, ty, lz, (cost + danger(c, lx, ty, lz)) * c.jitter(lx, ty, lz));
			}
		}
	}
}
